async function submitGlobalSearch(query){const result=await get('/api/radar/search',{q:query});if(result.kind==='token'){navigate(result.route);return;}if(result.kind==='unclassified'){renderSearchChoice(result);return;}showResult('SEARCH',`${result.items.length} RESULTS`);const root=$('result-content'),list=el('div',undefined,'search-results');for(const item of result.items){const button=el('button',`${item.symbol} / ${item.name} · ${short(item.address)} · SCORE ${item.score??'—'}`,`entity-link ${scoreTone(item.score)}`);button.addEventListener('click',()=>navigate(item.route));list.append(button);}root.append(result.items.length?list:el('div','No indexed tokens match this search.','empty-state'));}
